function localDateTimeV5(value){
  let date=value?new Date(value):new Date();
  let pad=number=>String(number).padStart(2,'0');
  return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
function appointmentDefaultsV5(){
  let start=new Date();start.setSeconds(0,0);let minutes=start.getMinutes();start.setMinutes(minutes<30?30:60);
  let end=new Date(start.getTime()+30*60000);
  return{start:localDateTimeV5(start),end:localDateTimeV5(end)};
}
function clientOptionsV5(selected='',includeEmpty=true){
  return `${includeEmpty?'<option value="">Sem cliente</option>':''}${(D.clients||[]).filter(client=>client.active).map(client=>`<option value="${client.id}" ${selected===client.id?'selected':''}>${E(client.name)}</option>`).join('')}`;
}
function profileOptionsV5(selected='',teamLabel='Equipe'){
  return `<option value="" ${!selected?'selected':''}>${E(teamLabel)}</option>${(D.profiles||[]).map(person=>`<option value="${person.user_id}" ${selected===person.user_id?'selected':''}>${E(person.display_name)}</option>`).join('')}`;
}
function appointmentModalV5(edit=false){
  let item=edit?(D.appointments||[]).find(row=>row.id===MD.id):null,defaults=appointmentDefaultsV5(),clientId=item?.client_id||MD.clientId||'',kind=item?.kind||MD.kind||'meeting';
  return `<div class="modalbg"><div class="modal"><div class="head"><div><small class="ey">${edit?'EDITAR COMPROMISSO':'AGENDA RÁPIDA'}</small><h2>${edit?'Atualizar reunião':'Agendar em poucos campos'}</h2></div><button class="btn ghost small" data-close>✕</button></div><div class="v5-modal-intro">Reuniões, briefings e alinhamentos ficam separados de eventos StoryMaker, horas contratadas e financeiro.</div><form id="appointmentFormV5" data-id="${item?.id||''}"><div class="formgrid"><div class="field"><label>Cliente</label><select name="client_id">${clientOptionsV5(clientId)}</select></div><div class="field"><label>Tipo</label><select name="kind">${[['briefing','Briefing'],['meeting','Reunião'],['alignment','Alinhamento'],['content_capture','Captação'],['other','Outro']].map(([value,label])=>`<option value="${value}" ${kind===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="field"><label>Título <small class="muted">(opcional — o app monta automaticamente)</small></label><input name="title" value="${E(item?.title||'')}" placeholder="Ex.: Briefing com a cliente"></div><div class="formgrid"><div class="field"><label>Início</label><input name="starts_at" type="datetime-local" required value="${item?localDateTimeV5(item.starts_at):defaults.start}"></div><div class="field"><label>Fim</label><input name="ends_at" type="datetime-local" required value="${item?localDateTimeV5(item.ends_at):defaults.end}"></div></div><div class="field"><label>Local ou link <small class="muted">(opcional)</small></label><input name="location_or_link" value="${E(item?.location_or_link||'')}" placeholder="Google Meet, endereço ou link"></div><div class="formgrid"><div class="field"><label>Lembrete</label><select name="reminder_minutes">${[[0,'Sem lembrete'],[15,'15 minutos antes'],[30,'30 minutos antes'],[60,'1 hora antes'],[1440,'1 dia antes']].map(([value,label])=>`<option value="${value}" ${Number(item?.reminder_minutes??30)===value?'selected':''}>${label}</option>`).join('')}</select></div>${edit?`<div class="field"><label>Status</label><select name="status">${[['scheduled','Agendada'],['completed','Concluída'],['cancelled','Cancelada']].map(([value,label])=>`<option value="${value}" ${item?.status===value?'selected':''}>${label}</option>`).join('')}</select></div>`:''}</div><details><summary class="muted">Adicionar observações</summary><div class="field"><textarea name="notes" rows="3" placeholder="Pauta ou informação importante">${E(item?.notes||'')}</textarea></div></details><div class="actions">${edit?`<button type="button" class="btn danger" data-appointmentdelete="${item?.id}">Excluir</button>`:''}<button class="btn pri">${edit?'Salvar alterações':'Agendar'}</button></div></form></div></div>`;
}
