  try{await api('/rest/v1/content_references',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:form.dataset.client,title,category:'idea',status:'idea',pinned:false,created_by:S.user.id})});input.value='';await load();render();toast('Ideia anotada')}catch(error){toast(error.message)}
