async function patchIdeaV5(id,payload,message){
  try{await patch('content_references',id,{...payload,updated_at:new Date().toISOString()});await load();render();toast(message)}catch(error){toast(error.message)}
}
async function transformIdeaV5(event){
  event.preventDefault();let form=event.currentTarget,data=new FormData(form),idea=(D.refs||[]).find(item=>item.id===form.dataset.id);if(!idea)return;
  let source=String(idea.source_url||'').trim(),payload={organization_id:M.organization_id,client_id:String(data.get('client_id')),title:String(data.get('title')).trim(),format:String(data.get('format')||'static_post'),objective:String(data.get('objective')||'').trim()||null,central_idea:String(data.get('central_idea')||'').trim()||null,internal_notes:idea.notes||null,reference_links:source?[source]:[],publication_date:String(data.get('publication_date')||'')||null,status:'idea',created_by:S.user.id};
  try{
    let response=await api('/rest/v1/contents',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)}),content=response?.[0];
    await patch('content_references',idea.id,{status:'converted',converted_content_id:content?.id||null,updated_at:new Date().toISOString()});
    contentClient=payload.client_id;contentMode='list';V='content';MD=content?.id?{type:'contentDetail',id:content.id}:null;await load();render();toast('Ideia transformada em conteúdo');
  }catch(error){toast(error.message)}
}
