  try{await api('/rest/v1/internal_library_items',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});MD=null;await load();render();toast('Link salvo na Biblioteca Colab')}catch(error){toast(error.message)}
