async function useTemplateV5(templateId,clientId){
  let template=(D.formTemplates||[]).find(item=>item.id===templateId),client=cl(clientId);if(!template||!client)return;
  try{
    if(template.form_type==='briefing'&&template.service==='storymaker'){
      let events=(D.events||[]).filter(item=>item.client_id===clientId&&item.event_type==='storymaker').sort((a,b)=>String(a.starts_at||'').localeCompare(String(b.starts_at||''))),event=events.find(item=>String(item.starts_at||'').slice(0,10)>=today())||events.at(-1);
      if(!event){MD={type:'storyEventNew',clientId};render();return toast('Cadastre o evento; depois o modelo será vinculado ao briefing dele')}
      let briefing=await ensureStoryBriefing(event.id);await patch('storymaker_briefings',briefing.id,{template_id:template.id,updated_at:new Date().toISOString()});await load();await copyStoryBriefing(event.id);return;
    }
    let onboarding=(D.onboardings||[]).find(item=>item.client_id===clientId);
    if(onboarding)await patch('client_onboardings',onboarding.id,{template_id:template.id,updated_at:new Date().toISOString()});
    else await api('/rest/v1/client_onboardings',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:clientId,template_id:template.id,answers:{},status:'draft'})});
    await load();render();
    let url=`${B}/functions/v1/client-onboarding?token=${encodeURIComponent(client.portal_preview_token)}`;await clientShareCopyTextV429(url);toast('Modelo aplicado e link do onboarding copiado');
  }catch(error){toast(error.message)}
}

function storyCheckCategoryV5(category){return({before:'ANTES DO EVENTO',event:'NO DIA DO EVENTO',after:'DEPOIS DO EVENTO',capture:'NO DIA DO EVENTO',restriction:'ATENÇÃO / RESTRIÇÕES'})[category]||'CHECKLIST'}
function storyCheckRowV5(item){
  return `<div class="v5-story-check"><input type="checkbox" ${item.completed?'checked':''} onchange="toggleStoryCheck('${item.id}',this.checked)"><div><b class="${item.priority==='high'||item.priority==='urgent'?'story-priority':''}">${E(item.title)}</b><small>${item.source==='briefing'?'Gerado do briefing':'Criado pela equipe'}${item.notes?' · '+E(item.notes):''}</small></div><div class="v5-story-check-controls"><select data-storycheckowner="${item.id}" aria-label="Responsável">${profileOptionsV5(item.assigned_to,'Equipe')}</select><input data-storychecktime="${item.id}" type="time" value="${E(String(item.scheduled_time||'').slice(0,5))}" aria-label="Horário"></div></div>`;
}
const _storyDetailChecklistV5Base=storymakerDetailModal;
storymakerDetailModal=function(id){
  let html=_storyDetailChecklistV5Base(id),items=(D.storyChecklist||[]).filter(item=>item.event_id===id).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order));if(!html||!items.length)return html;
  let start=html.indexOf('<section class="story-section"><div class="head"><div><small class="ey">CAPTAÇÃO</small><h3>Prioridades e checklist</h3>');
  if(start<0)start=html.indexOf('<section class="story-section"><div class="head"><div><small class="ey">CAPTAÇÃO</small><h3>Checklist do dia</h3>');
  if(start<0)return html;let end=html.indexOf('</section>',start);if(end<0)return html;end+='</section>'.length;
  let done=items.filter(item=>item.completed).length,pct=Math.round(done/items.length*100),groups=['before','event','after','restriction'];
  let section=`<section class="story-section"><div class="head"><div><small class="ey">CHECKLIST OPERACIONAL</small><h3>Antes, durante e depois</h3></div><button class="btn ghost small" onclick="addStoryCheck('${id}')">＋ Item</button></div><div class="v5-check-summary"><div class="v5-progress-large"><i style="width:${pct}%"></i></div><b>${done}/${items.length}</b></div><div class="v5-check-groups">${groups.map(group=>{let rows=items.filter(item=>(group==='event'?['event','capture'].includes(item.category):item.category===group));return rows.length?`<div class="v5-check-group"><h4>${storyCheckCategoryV5(group)}</h4>${rows.map(storyCheckRowV5).join('')}</div>`:''}).join('')}${items.filter(item=>!['before','event','capture','after','restriction'].includes(item.category)).length?`<div class="v5-check-group"><h4>OUTROS</h4>${items.filter(item=>!['before','event','capture','after','restriction'].includes(item.category)).map(storyCheckRowV5).join('')}</div>`:''}</div></section>`;
  return html.slice(0,start)+section+html.slice(end);
};

let storySyncingV5=new Set();
async function syncStoryChecklistV5(eventId){
  if(storySyncingV5.has(eventId))return false;let briefing=(D.storyBriefings||[]).find(item=>item.event_id===eventId);if(!briefing?.submitted_at)return false;
  storySyncingV5.add(eventId);
  try{
    let schedule=sbObj(briefing.schedule_details),items=[],order=0,add=(key,title,category='event',priority='normal',notes=null,time=null)=>{title=String(title||'').trim();if(!title)return;items.push({organization_id:M.organization_id,event_id:eventId,source_key:key,title,category,priority,source:'briefing',sort_order:order++,notes:notes||null,scheduled_time:/^\d{2}:\d{2}/.test(String(time||''))?String(time).slice(0,5):null})};
    if(briefing.schedule_url||Object.keys(schedule).length)add('before_schedule','Revisar cronograma, horários e deslocamentos','before','high',briefing.schedule_url?'Cronograma vinculado no briefing':null);
    if(briefing.stories_publish_handle)add('before_instagram','Confirmar acesso ao Instagram '+briefing.stories_publish_handle,'before','high');
    if(sbArr(briefing.visual_identity_files).length)add('before_identity','Separar a identidade visual do casamento','before');
    let media=sbObj(schedule.media_professionals);if(media.present)add('before_media','Alinhar posições com os outros profissionais de mídia','before','normal',media.notes||null);
    if(briefing.mark_suppliers||String(schedule.visible_mentions_choice||''))add('before_mentions','Revisar fornecedores e formato das marcações','before','normal',schedule.visible_mentions_choice==='no'?'Marcações discretas':'Marcações visíveis');
    let coverageLabels={bride:'Making of da noiva',groom:'Making of do noivo',first_look:'First look',ceremony:'Cerimônia',reception:'Recepção e festa',other:'Outro momento combinado'};
    sbArr(briefing.coverage_items).forEach((value,index)=>{let time=schedule[value+'_time']||schedule[(value==='bride'?'bride':value)+'_time'];add('coverage_'+value+'_'+index,'Cobrir '+(coverageLabels[value]||value),'event','normal',schedule[value+'_location']||null,time)});
    sbArr(briefing.must_capture_items).forEach((value,index)=>{let title=typeof value==='string'?value:value?.title||value?.moment||value?.name;add('must_'+index,title,'event','urgent')});
    sbArr(briefing.important_people_items).forEach((person,index)=>add('person_'+index,'Registrar reações de '+(person?.name||'pessoa importante'),'event','high',person?.relation||null));
    sbArr(briefing.supplier_items).filter(item=>item?.kind==='partnership').forEach((partner,index)=>add('partnership_'+index,'Captação da parceria: '+(partner.name||'parceria'),'event','high',partner.capture||partner.notes||null));
    if(briefing.must_moment)add('specific_moment','Momento específico: '+briefing.must_moment,'event','urgent');
    if(briefing.must_reaction)add('specific_reaction','Reação específica: '+briefing.must_reaction,'event','urgent');
    if(briefing.must_specific)add('specific_detail','Detalhe com significado: '+briefing.must_specific,'event','high');
    if(briefing.do_not_capture)add('restriction_capture','Não filmar: '+briefing.do_not_capture,'restriction','urgent');
    if(briefing.do_not_publish)add('restriction_publish','Não publicar: '+briefing.do_not_publish,'restriction','high');
    (D.storyDeliverables||[]).filter(item=>item.event_id===eventId).forEach((deliverable,index)=>add('deliverable_'+deliverable.id,'Preparar entrega: '+deliverable.title,'after','normal'));
    if(briefing.publication_permission)add('after_permission','Registrar autorização de uso no perfil da Colab','after');
    let existing=(D.storyChecklist||[]).filter(item=>item.event_id===eventId&&item.source==='briefing'&&item.source_key),desired=new Map(items.map(item=>[item.source_key,item])),operations=[];
    existing.filter(item=>!desired.has(item.source_key)).forEach(item=>operations.push(api('/rest/v1/storymaker_checklist_items?id=eq.'+item.id,{method:'DELETE',headers:{Prefer:'return=minimal'}})));
    existing.filter(item=>desired.has(item.source_key)).forEach(item=>{let next=desired.get(item.source_key),change={};['title','category','priority','sort_order','notes','scheduled_time'].forEach(key=>{if(String(item[key]??'')!==String(next[key]??''))change[key]=next[key]});if(Object.keys(change).length)operations.push(patch('storymaker_checklist_items',item.id,{...change,updated_at:new Date().toISOString()}));desired.delete(item.source_key)});
    let missing=[...desired.values()];if(missing.length)operations.push(api('/rest/v1/storymaker_checklist_items',{method:'POST',headers:{Prefer:'return=minimal,missing=default'},body:JSON.stringify(missing)}));
    if(!operations.length)return false;await Promise.all(operations);await load();return true;
  }catch(error){console.warn('Checklist automático',error);return false}finally{storySyncingV5.delete(eventId)}
}
