vitrinePageV5=function(){
  let now=today(),weekEnd=new Date(now+'T12:00:00');weekEnd.setDate(weekEnd.getDate()+7);let end=weekEnd.toISOString().slice(0,10);
  let clients=(D.clients||[]).filter(item=>item.active),openTasks=sortedTasksV5((D.tasks||[]).filter(item=>item.status!=='done'));
  let urgent=openTasks.filter(item=>item.priority==='urgent'||(item.due_date&&item.due_date<now)).slice(0,6);
  let contents=D.contents||[],approvals=(D.approvals||[]).filter(item=>item.status==='pending'),events=(D.events||[]).filter(item=>String(item.starts_at||'').slice(0,10)>=now).sort((a,b)=>String(a.starts_at).localeCompare(String(b.starts_at)));
  let appointments=(D.appointments||[]).filter(item=>item.status==='scheduled'&&String(item.starts_at).slice(0,10)>=now&&String(item.starts_at).slice(0,10)<=end).sort((a,b)=>String(a.starts_at).localeCompare(String(b.starts_at)));
  let checks=D.storyChecklist||[],checkDone=checks.filter(item=>item.completed).length,checkPct=checks.length?Math.round(checkDone/checks.length*100):0;
  let doing=openTasks.filter(item=>item.status==='doing').length+contents.filter(item=>['production','editing'].includes(item.status)).length;
  let contentForApproval=id=>{let approval=approvals.find(item=>item.id===id);return approval?.contents||contents.find(item=>item.id===approval?.content_id)};
  let clientCards=clients.slice(0,6).map(client=>{let services=(D.services||[]).filter(item=>item.client_id===client.id&&item.active),tasks=openTasks.filter(item=>item.client_id===client.id),pending=approvals.filter(item=>(item.contents?.client_id||contents.find(content=>content.id===item.content_id)?.client_id)===client.id).length,nextEvent=events.find(item=>item.client_id===client.id);return`<article class="v539-client-card"><div class="v539-client-top"><span class="avatar">${E(client.initials||ini(client.name))}</span><span class="v539-live-tag"><i></i> ATIVO</span></div><h3>${E(client.name)}</h3><p>${E(client.segment||'Cliente Colab')}</p><div class="chips">${services.map(item=>`<span class="tag o">${E(lab(item.service))}</span>`).join('')||'<span class="tag">Operação ativa</span>'}</div><div class="v539-client-numbers"><span><b>${tasks.length}</b> demandas</span><span><b>${pending}</b> aprovações</span></div>${nextEvent?`<small>Próximo evento · ${fmtDate(String(nextEvent.starts_at).slice(0,10))}</small>`:'<small>Rotina acompanhada pela Colab</small>'}</article>`}).join('');
  let pipeline=[['Ideias',contents.filter(item=>item.status==='idea').length],['Produção',contents.filter(item=>['production','editing','script'].includes(item.status)).length],['Aprovação',approvals.length],['Programados',contents.filter(item=>item.status==='scheduled').length],['Publicados',contents.filter(item=>item.status==='published').length]];
  let agenda=[...appointments.map(item=>({date:item.starts_at,title:item.title,meta:(cl(item.client_id)?.name||'Colab')+' · '+appointmentKindLabelV5(item.kind)})),...events.filter(item=>String(item.starts_at).slice(0,10)<=end).map(item=>({date:item.starts_at,title:item.title,meta:(cl(item.client_id)?.name||'Cliente')+' · '+lab(item.event_type)}))].sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(0,7);
  let team=(D.profiles||[]).map(person=>{let mine=openTasks.filter(item=>item.assigned_to===person.user_id),active=mine.filter(item=>item.status==='doing').length,late=mine.filter(item=>item.due_date&&item.due_date<now).length;return`<article class="v539-team-card"><span class="avatar">${E(ini(person.display_name))}</span><div><h4>${E(person.display_name)}</h4><p>${active?active+' em execução':'Disponível para novas demandas'}</p></div><div><b>${mine.length}</b><small>abertas</small>${late?`<em>${late} atrasada${late>1?'s':''}</em>`:''}</div></article>`}).join('');
  let activeStories=events.filter(item=>item.event_type==='storymaker').slice(0,4);
  return `<main class="v5-showcase v539-showcase"><header class="v5-showcase-top v539-top"><div class="v5-showcase-brand"><div class="logo">C<span>O</span>LAB</div><span class="v5-showcase-badge">SISTEMA OPERACIONAL</span></div><div class="actions"><span class="v539-live-tag"><i></i> DADOS ATUALIZADOS</span><button class="btn ghost" data-showcase-refresh>↻ Atualizar</button><button class="btn pri" data-showcase-exit>Fechar vitrine</button></div></header>
  <section class="v539-hero"><div><small class="ey">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).toUpperCase()}</small><h1>Central operacional<br><em>Colab.</em></h1><p>Clientes, estratégia, conteúdo, eventos, entregas e financeiro conectados em uma única operação.</p><div class="v539-module-rail"><span>Clientes</span><span>Conteúdos</span><span>Demandas</span><span>Eventos</span><span>Financeiro</span><span>Portal</span></div></div><aside><small>OPERAÇÃO AGORA</small><b>${openTasks.length+contents.filter(item=>item.status!=='published').length+events.length}</b><p>movimentos acompanhados pelo sistema</p><div><span><strong>${doing}</strong> em produção</span><span><strong>${approvals.length}</strong> aprovações</span><span><strong>${urgent.length}</strong> prioridades</span></div></aside></section>
  <section class="v539-kpis"><article><span>CLIENTES ATIVOS</span><b>${clients.length}</b><small>operações por cliente</small></article><article><span>DEMANDAS ABERTAS</span><b>${openTasks.length}</b><small>com prazo e responsável</small></article><article><span>CONTEÚDOS</span><b>${contents.length}</b><small>do planejamento à publicação</small></article><article><span>PRÓXIMOS EVENTOS</span><b>${events.length}</b><small>captações e entregas</small></article><article><span>A RECEBER</span><b>${money(receivableOpenV5())}</b><small>controle financeiro</small></article><article><span>CHECKLISTS</span><b>${checkPct}%</b><small>${checkDone} de ${checks.length} concluídos</small></article></section>
  <div class="v539-main-grid"><section class="v539-panel v539-priorities"><div class="v539-section-head"><div><small class="ey">DEMANDAS PRIORITÁRIAS</small><h2>O que precisa de ação</h2></div><span>${urgent.length}</span></div>${urgent.map(taskCompactRowV5).join('')||'<div class="v539-empty">Nenhuma demanda urgente ou atrasada.</div>'}</section><section class="v539-panel"><div class="v539-section-head"><div><small class="ey">CARTEIRA ATIVA</small><h2>Operação por cliente</h2></div><span>${clients.length}</span></div><div class="v539-client-grid">${clientCards||'<div class="v539-empty">Nenhum cliente ativo.</div>'}</div></section></div>
  <section class="v539-panel v539-flow"><div class="v539-section-head"><div><small class="ey">FLUXO EDITORIAL</small><h2>Da ideia à publicação</h2></div><p>O calendário é consequência do planejamento e da produção.</p></div><div class="v539-pipeline">${pipeline.map(([label,count],index)=>`<article class="${count?'active':''}"><small>0${index+1}</small><b>${count}</b><span>${E(label)}</span><i></i></article>`).join('')}</div></section>
  <div class="v539-triple"><section class="v539-panel"><small class="ey">PRÓXIMOS 7 DIAS</small><h2>Agenda da operação</h2><div class="v539-agenda">${agenda.map(item=>`<div><time>${fmtDate(String(item.date).slice(0,10))}<b>${fmtTime(item.date)||''}</b></time><span><strong>${E(item.title)}</strong><small>${E(item.meta)}</small></span></div>`).join('')||'<div class="v539-empty">Nenhum compromisso programado.</div>'}</div></section><section class="v539-panel v539-story"><small class="ey">STORYMAKER</small><h2>Eventos e captações</h2><div class="v539-story-progress"><b>${checkPct}%</b><span><i style="width:${checkPct}%"></i></span><small>${checkDone} de ${checks.length} etapas concluídas</small></div>${activeStories.map(item=>`<div class="v539-story-row"><span>${fmtDate(String(item.starts_at).slice(0,10))}</span><b>${E(cl(item.client_id)?.name||item.title)}</b><small>${E(item.location||'Local a confirmar')}</small></div>`).join('')||'<div class="v539-empty">Nenhum evento StoryMaker próximo.</div>'}</section><section class="v539-panel v539-money"><small class="ey">FINANCEIRO</small><h2>Visão financeira</h2><article><span>Caixa atual</span><b>${money(cashNowV5())}</b></article><article><span>A receber</span><b class="pos">${money(receivableOpenV5())}</b></article><article><span>A pagar</span><b class="neg">${money(payableOpenV5())}</b></article></section></div>
  <section class="v539-panel"><div class="v539-section-head"><div><small class="ey">EQUIPE EM MOVIMENTO</small><h2>Responsáveis e execução</h2></div><p>Cada demanda tem responsável, prioridade e prazo.</p></div><div class="v539-team-grid">${team||'<div class="v539-empty">Equipe ainda não cadastrada.</div>'}</div></section></main>`;
};

