goalsPage=function(){let goals=regularGoals(),revenue=goals.find(goal=>goal.metric_key==='revenue'),actual=revenue?goalActualV542(revenue):0,target=Number(revenue?.target_value||0),remaining=Math.max(0,target-actual),days=Math.max(1,new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()-new Date().getDate()+1),fees=(D.contracts||[]).filter(contract=>contract.status==='active').map(contract=>Number(contract.monthly_fee||0)).filter(Boolean),ticket=fees.length?fees.reduce((a,b)=>a+b,0)/fees.length:0,needed=ticket?Math.ceil(remaining/ticket):null,forecast=forecastV542();return`<section class="hero v542-plan-hero"><div><small class="ey">PLANEJAMENTO FINANCEIRO</small><h2>Meta, ritmo e previsibilidade</h2><p class="muted">Os números abaixo são atualizados pelos clientes ativos, contratos e recebimentos pagos.</p></div></section><div class="v542-plan-kpis"><article><span>REALIZADO NO MÊS</span><b>${money(actual)}</b></article><article><span>FALTA PARA A META</span><b>${money(remaining)}</b></article><article><span>PREVISÃO COM PIPELINE</span><b>${money(forecast)}</b></article><article><span>RITMO NECESSÁRIO</span><b>${money(remaining/days)}<small>/dia</small></b></article></div>${target?`<section class="panel v542-goal-main"><div class="head"><div><small class="ey">META DO MÊS</small><h3>${money(actual)} de ${money(target)}</h3></div><b class="goalpercent">${Math.round(actual/target*100)}%</b></div><div class="progress goalprogress"><i style="width:${Math.min(100,actual/target*100)}%"></i></div><p class="muted">${remaining?ticket?`Com ticket médio de ${money(ticket)}, faltam aproximadamente ${needed} novo${needed===1?' contrato':'s contratos'} para alcançar a meta.`:`Cadastre os valores dos contratos para calcular quantos fechamentos ainda faltam.`:'Meta alcançada. O sistema registrará a comemoração automaticamente.'}</p><div class="field"><label>Valor da próxima meta</label><input id="goalTarget_${revenue.id}" type="number" step="100" min="0" value="${target}"></div><button class="btn ghost full" data-goalsave="${revenue.id}">Atualizar somente a meta</button></section>`:''}<div class="goalgrid">${goals.filter(goal=>goal.id!==revenue?.id).map(goal=>{let actual=goalActualV542(goal);return`<article class="panel goalcard"><div class="head"><div><small class="ey">${E(goal.period_label||'META')}</small><h3>${E(goal.title)}</h3></div><b class="goalpercent">${Math.round(goalPct(goal))}%</b></div><div class="progress goalprogress"><i style="width:${goalPct(goal)}%"></i></div><p class="goalnumber">${E(goalValue(goal,actual))} <span>de ${E(goalValue(goal,goal.target_value))}</span></p>${['clients','lifetime_revenue','partnerships'].includes(goal.metric_key)?'<div class="note">Atualização automática pelos dados reais do sistema.</div>':`<div class="field"><label>Valor atual</label><input id="goalCurrent_${goal.id}" type="number" min="0" value="${Number(goal.current_value||0)}"></div>`}<div class="field"><label>Próxima meta</label><input id="goalTarget_${goal.id}" type="number" min="0" value="${Number(goal.target_value||0)}"></div><button class="btn ghost full" data-goalsave="${goal.id}">Atualizar meta</button></article>`}).join('')}</div>`};
