clientPaymentMetaV5=function(clientId){
  let monthly=sum((D.contracts||[]).filter(contract=>contract.client_id===clientId&&contract.status==='active'),'monthly_fee');
  if(monthly>0)return{label:'Mensalidade',cls:'g',detail:money(monthly)};
  let pending=(D.receivables||[]).filter(item=>item.client_id===clientId&&item.status==='pending').sort((a,b)=>String(a.competence_month||a.due_date).localeCompare(String(b.competence_month||b.due_date)));
  if(!pending.length)return{label:'Em dia',cls:'g',detail:'Sem pendências'};
  let month=String(pending[0].competence_month||pending[0].due_date).slice(0,7),next=pending.filter(item=>String(item.competence_month||item.due_date).slice(0,7)===month),late=next.some(item=>item.due_date<today());
  return{label:late?'Pagamento atrasado':'Próximo recebimento',cls:late?'r':'y',detail:money(sum(next,'amount'))};
};

