function recoverySessionV548(){
  let hash=new URLSearchParams(location.hash.replace(/^#/,''));
  if(hash.get('type')!=='recovery')return null;
  return{access_token:hash.get('access_token')||'',refresh_token:hash.get('refresh_token')||'',error:hash.get('error_description')||hash.get('error')||''};
}
function recoveryPasswordPageV548(recovery,message=''){
  if(recovery.error||!recovery.access_token){
    MODE='login';
    history.replaceState({},'',location.pathname+location.search);
    return auth('Este link expirou ou não é válido. Solicite uma nova redefinição de senha.');
  }
  R.innerHTML=`<div class="auth"><section class="brand"><div><div class="logo">C<span>O</span>LAB</div><small>SEU ESCRITÓRIO CRIATIVO</small></div><div><small class="ey">CENTRAL COLAB</small><h1>Um novo acesso.<br><em>A mesma Colab.</em></h1><p class="muted">Escolha uma senha segura para continuar.</p></div></section><section class="login"><div class="authcard"><small class="ey">REDEFINIR SENHA</small><h2>Crie uma nova senha</h2><p class="muted">Ela deve ter pelo menos 6 caracteres.</p>${message?`<div class="msg">${E(message)}</div>`:''}<form id="recoveryPasswordFormV548"><div class="field"><label>Nova senha</label><input name="password" type="password" required minlength="6" autocomplete="new-password"></div><div class="field"><label>Confirme a nova senha</label><input name="confirmation" type="password" required minlength="6" autocomplete="new-password"></div><button class="btn pri full">Salvar nova senha</button></form></div></section></div>`;
  document.getElementById('recoveryPasswordFormV548').onsubmit=event=>saveRecoveredPasswordV548(event,recovery);
}
async function saveRecoveredPasswordV548(event,recovery){
  event.preventDefault();
  let form=event.currentTarget,data=new FormData(form),password=String(data.get('password')||''),confirmation=String(data.get('confirmation')||''),button=form.querySelector('button');
  if(password!==confirmation)return recoveryPasswordPageV548(recovery,'As duas senhas precisam ser iguais.');
  button.disabled=true;button.textContent='Salvando…';
  try{
    let response=await tf(B+'/auth/v1/user',{method:'PUT',headers:{apikey:K,Authorization:'Bearer '+recovery.access_token,'Content-Type':'application/json'},body:JSON.stringify({password})}),payload=await response.json().catch(()=>({}));
    if(!response.ok)throw Error(payload.msg||payload.message||payload.error_description||'Não foi possível redefinir a senha.');
    clear();MODE='login';history.replaceState({},'',location.pathname);auth('Senha redefinida. Agora entre com a sua nova senha.');
  }catch(error){recoveryPasswordPageV548(recovery,error.message||'Não foi possível redefinir a senha.');}
}
async function requestPasswordRecoveryV548(event){
  event.preventDefault();
  let form=event.currentTarget,email=String(new FormData(form).get('email')||'').trim().toLowerCase(),button=form.querySelector('button');
  button.disabled=true;button.textContent='Enviando…';
  try{
    let redirect=location.origin+'/',response=await tf(B+'/auth/v1/recover?redirect_to='+encodeURIComponent(redirect),{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:JSON.stringify({email})}),payload=await response.json().catch(()=>({}));
    if(!response.ok)throw Error(payload.msg||payload.message||payload.error_description||'Não foi possível enviar o e-mail.');
    MODE='login';auth('Se este e-mail estiver cadastrado, você receberá o link para criar uma nova senha. Confira também a caixa de spam.');
  }catch(error){authRecoveryV548(error.message||'Não foi possível enviar o e-mail.');}
}
function authRecoveryV548(message=''){
  MODE='recover';
  R.innerHTML=`<div class="auth"><section class="brand"><div><div class="logo">C<span>O</span>LAB</div><small>SEU ESCRITÓRIO CRIATIVO</small></div><div><small class="ey">CENTRAL COLAB</small><h1>Recupere seu<br><em>acesso.</em></h1><p class="muted">Você receberá um link seguro no e-mail cadastrado.</p></div></section><section class="login"><div class="authcard"><small class="ey">RECUPERAR ACESSO</small><h2>Esqueci minha senha</h2><p class="muted">Informe o e-mail usado na COLAB.</p>${message?`<div class="msg">${E(message)}</div>`:''}<form id="recoveryEmailFormV548"><div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email" autofocus></div><button class="btn pri full">Enviar link de redefinição</button></form><button id="recoveryBackV548" class="btn full v548-auth-link">Voltar para entrar</button></div></section></div>`;
  document.getElementById('recoveryEmailFormV548').onsubmit=requestPasswordRecoveryV548;
  document.getElementById('recoveryBackV548').onclick=()=>{MODE='login';auth()};
}
auth=function(msg=''){
  if(MODE==='recover')return authRecoveryV548(msg);
  let login=MODE==='login';
  R.innerHTML=`<div class="auth"><section class="brand"><div><div class="logo">C<span>O</span>LAB</div><small>SEU ESCRITÓRIO CRIATIVO</small></div><div><small class="ey">CENTRAL COLAB</small><h1>Nossa <em>Colab</em><br>começa aqui.</h1><p class="muted">Seu escritório criativo, em um só lugar.</p></div></section><section class="login"><div class="authcard"><small class="ey">ACESSO</small><h2>${login?'Vamos fazer uma Colab?':'Crie seu acesso'}</h2><p class="muted">${login?'Entre para acessar seu escritório criativo.':'Cadastre seu e-mail.'}</p>${msg?`<div class="msg">${E(msg)}</div>`:''}<form id="af"><div class="field"><label>E-mail</label><input name="email" type="email" required autocomplete="email"></div><div class="field"><label>Senha</label><input name="password" type="password" required minlength="6" autocomplete="${login?'current-password':'new-password'}"></div><button class="btn pri full">${login?'Entrar':'Criar conta'}</button></form>${login?'<button id="forgotPasswordV548" class="btn full v548-forgot">Esqueci minha senha</button>':''}<button id="mode" class="btn full v548-auth-link">${login?'Primeiro acesso':'Já tenho acesso'}</button></div></section></div>`;
  document.getElementById('mode').onclick=()=>{MODE=login?'signup':'login';auth()};
  document.getElementById('forgotPasswordV548')?.addEventListener('click',()=>authRecoveryV548());
  document.getElementById('af').onsubmit=doAuth;
};
boot=async function(){
  let recovery=recoverySessionV548();
  if(recovery)return recoveryPasswordPageV548(recovery);
  S=read();if(!S)return setTimeout(()=>auth(),350);save(S);
  try{if(S.expires_at&&S.expires_at*1000<Date.now()+30000&&!await refresh())return auth();await hydrate()}catch(error){console.error(error);clear();auth('Não consegui restaurar sua sessão. Entre novamente.');}
};
