vitrinePageV5=function(){
  let now=today(),first=(profile(S.user?.id)?.display_name||'Thalia').split(' ')[0],endDate=new Date(now+'T12:00:00');endDate.setDate(endDate.getDate()+14);let end=endDate.toISOString().slice(0,10);
  let appointments=(D.appointments||[]).filter(item=>item.status==='scheduled'&&String(item.starts_at).slice(0,10)>=now&&String(item.starts_at).slice(0,10)<=end).map(item=>({date:item.starts_at,title:appointmentKindLabelV5(item.kind),type:'Agenda'}));
  let events=(D.events||[]).filter(item=>String(item.starts_at||'').slice(0,10)>=now&&String(item.starts_at||'').slice(0,10)<=end).map(item=>({date:item.starts_at,title:item.event_type==='storymaker'?'Captação StoryMaker':lab(item.event_type),type:'Evento'}));
  let deadlines=(D.tasks||[]).filter(item=>item.status!=='done'&&item.due_date>=now&&item.due_date<=end).map(item=>({date:item.due_date,title:item.service==='social_media'?'Entrega de conteúdo':'Demanda programada',type:'Demanda'}));
  let agenda=[...appointments,...events,...deadlines].sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(0,5);
  let journey=[['Proposta','escopo'],['Onboarding','imersão'],['Briefing','informações'],['Estratégia','direção'],['Planejamento','ritmo'],['Conteúdo','produção'],['Aprovação','validação'],['Publicação','presença']];
  let operation=[['DESCOBERTA',['Ideias e insights','DNA Colab']],['DIREÇÃO',['Estratégia','Planejamento','Linhas editoriais']],['PRODUÇÃO',['Roteiros','Conteúdos','Demandas']],['VALIDAÇÃO',['Aprovações','Calendário','Eventos']]];
  let header=`<header class="top"><div><small class="ey">COLAB OPERACIONAL</small><h1>PAINEL DE COMANDO</h1></div><div class="topactions"><button class="bell" type="button" aria-label="Notificações"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg></button><button class="btn ghost v5-top-btn v5-eye-btn" data-showcase-exit aria-label="Alternar visualização">${v5EyeIcon()}</button></div></header>`;
  let hero=`<section class="hero office-hero v539-home-return v549-hero"><div><small class="ey">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).toUpperCase()}</small><h2>Olá, ${E(first)}.</h2><div class="mode-on">Modo Colab: <b>ON</b><span class="mode-dot" aria-hidden="true"></span></div>${dailyWord()}</div><div class="v5-quick-grid"><span class="btn pri"><b>＋</b> Demanda</span><span class="btn ghost"><b>＋</b> Conteúdo</span><span class="btn ghost"><b>＋</b> Evento</span></div></section>`;
  return `<div class="shell v546-shell v549-shell"><aside class="side"><div class="logo">C<span>O</span>LAB</div><nav class="nav">${v5NavHtml()}</nav></aside><main class="main">${header}${hero}<section class="panel v549-method"><div class="v549-method-copy"><small class="ey">MÉTODO COLAB</small><h2>Da entrada da cliente<br>à publicação.</h2><p>Estratégia, criação e operação conectadas no mesmo fluxo.</p><div class="v549-models"><span>MODELOS COLAB</span><b>Propostas</b><b>Onboarding</b><b>Briefing</b></div></div><div class="v549-journey">${journey.map(([name,detail],index)=>`<article class="${index===journey.length-1?'finish':''}"><i>${index===journey.length-1?'✓':'●'}</i><div><b>${name}</b><small>${detail}</small></div></article>`).join('')}</div></section><section class="panel v549-operation"><div class="v549-operation-title"><small class="ey">OPERAÇÃO EDITORIAL</small><h2>Tudo o que sustenta<br>uma presença estratégica.</h2><span>✦</span></div><div class="v549-operation-map">${operation.map(([phase,items])=>`<article><small>${phase}</small>${items.map(item=>`<b>${item}</b>`).join('')}</article>`).join('')}</div></section><div class="v549-bottom"><section class="panel v549-agenda"><div class="head"><div><small class="ey">AGENDA COLAB</small><h2>Próximos compromissos</h2></div><span class="v549-outline-icon">□</span></div><div class="v546-agenda">${agenda.map(item=>`<article><time>${fmtDate(String(item.date).slice(0,10))}<b>${fmtTime(item.date)||''}</b></time><span><b>${E(item.title)}</b><small>${E(item.type)}</small></span><em>→</em></article>`).join('')||'<div class="v5-empty-soft">Agenda organizada para os próximos dias.</div>'}</div></section><section class="panel v549-services"><div><small class="ey">ECOSSISTEMA COLAB</small><h2>Estratégia que vira movimento.</h2></div><div class="v549-service-line"><span>Social Media</span><i>×</i><span>StoryMaker</span><i>×</i><span>Tráfego Pago</span><i>×</i><span>Identidade Visual</span></div></section></div></main></div>`;
};
