  try{if(id)await patch('social_media_reports',id,payload);else await api('/rest/v1/social_media_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({...payload,created_by:S.user?.id})});contentMonth=dateMonth(period);MD=null;await load();render();toast(payload.status==='published'?'Relatório publicado no portal':'Rascunho salvo')}
